---attrNode点击回调
function CardProgressionEquipmentRecastDialog:AttrNodeOnClickHandler(index)
    if self._autoModel then return end
    
    local equipDojo = self:GetEquipDojo()
    if index > checkInt(equipDojo.star) then
        -- 锁定属性不可点击
        GameUtils.Toast(localize("_num_星解锁", {_num_ = index}))
        return
    end
    
    if index == self._selectedAttrIdx then
        self._selectedAttrIdx = nil
        local scr = self:GetAttrNodeScr(index)
        scr:RefreshSelectedState(false)
        self:RefreshAttrs()
        self:RefreshConsume()
        self:RefreshButton()
        return 
    end

    if checkInt(self._selectedAttrIdx) > 0 then
        local scr = self:GetAttrNodeScr(self._selectedAttrIdx)
        scr:RefreshSelectedState(false)
    end
    
    self._selectedAttrIdx = index
    local scr = self:GetAttrNodeScr(index)
    scr:RefreshSelectedState(true)
    self:RefreshAttrs()
    self:RefreshConsume()
    self:RefreshButton()
end

