---提高按钮点击回调
function CardProgressionEquipmentRecastDialog:CuringBtnOnClickHandler(index)
    if self._autoModel then return end
    
    local equipDojo = self:GetEquipDojo()
    local equipmentId = equipDojo.equipmentId
    local id = equipDojo[string.format('attr%dId', index)]
    local num = equipDojo[string.format('attr%dNum', index)]
    local percent = EquipUtils.GetSubAttrPercent(equipmentId, id, num)
    if tonumber(percent) == 1 then
        GameUtils.Toast(localize("属性值已达上限"))
        return 
    end
    
    local goodsId = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentCuringGoodsId))
    local goodsNum = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentCuringGoodsNum))
    local consume = {{
        goodsId = goodsId,
        num = goodsNum
    }}
    local consumes, errorTips = GoodsUtils.CheckGoodConsume(consume)
    if errorTips then
        GameUtils.Toast(errorTips)
        return
    end
    
    local request = function ()
        local requestData = {
            playerEquipmentId = self:GetEquipDojo().id,
            enhancePosition = index
        }
        CardProgressionMgr:RequestOverseaEquipmentCuring(requestData, consumes, Bind(self, self.EquipmentCuringResponseHandler))
    end

    if self:CheckShowSecondConfirm() then
        self._secondConfirmTick = false
        local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
        GameUtils.SecondConfirm(
                localize("是否消耗_num_个_name_增加该条属性值？", {_num_ = goodsNum, _name_ = goodsVo.name}),
                function()
                    if self._secondConfirmTick == true then
                        CfUtils.WriteLocalData("EquipmentCuringSecondConfirm", GameUtils.GetServerTime())
                    end
                    request()
                end,
                nil,
                nil,
                4,
                consume,
                true,
                localize("属性条目不会改变，只随机提升属性值"),
                Bind(self, self.SecondConfirmTickChangeHandler)
        )
    else
        request()
    end
end

