---刷新几率页面
function CardProgressionEquipmentRecastDialog:RefreshChanceTipsDialog()
    local equipDojo = self:GetEquipDojo()
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local subAttrProbVo = CfUtils.GetCf(AutoIds.IdSetting6041, "EquipmentSubAttrProbVo", true)
    local attrList = {}
    local totalWeight = 0
    for _, v in ipairs(subAttrProbVo) do
        if v.purifyid == equipVo.poolSub then
            if attrList[v.attTypeId] then
                if v.starterdown < attrList[v.attTypeId].starterdown then
                    attrList[v.attTypeId].starterdown = v.starterdown
                end
                if v.starterup > attrList[v.attTypeId].starterup then
                    attrList[v.attTypeId].starterup = v.starterup
                end
            else
                totalWeight = totalWeight + v.weight
                local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(v.attTypeId)
                attrList[v.attTypeId] = {
                    weight       = v.weight,
                    name         = attrAdditionVo.attrAdditionName,
                    isConversion = attrAdditionVo.isConversion,
                    starterup    = v.starterup,
                    starterdown  = v.starterdown
                }
            end
        end
    end
    
    local function refreshNode(node, data, index)
        local text1 = node.transform:Find("Text1")
        CfUtils.FillText(text1, data.name)
        local text2 = node.transform:Find("Text2")
        local num = data.weight / totalWeight * 100
        CfUtils.FillText(text2,  string.format('%.2f%%', num))
        local text3 = node.transform:Find("Text3")
        CfUtils.FillText(text3, string.format("%s~%s", tostring(attribute_format(data.isConversion, data.starterdown)), tostring(attribute_format(data.isConversion, data.starterup))))
        local bg = node.transform:Find("ImgBg")
        CfUtils.SetActive(bg, not (index % 2 == 0))
    end
    
    local num = 1
    for k, v in pairs(attrList) do
        if num == 1 then
            refreshNode(self.ChanceItem, v, num)
        else
            local node = self.ChanceListGroup.gameObject:AddChild(self.ChanceItem.gameObject)
            refreshNode(node, v, num)
        end
        num = num + 1
    end
end

---刷新道具需求节点
function CardProgressionEquipmentRecastDialog:RefreshGoodsConsumeNode(gameObject, consume)
    local img = gameObject.transform:Find('ImgIcon')
    if isNull(img) then return end

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(consume.goodsId)
    CfUtils.FillImage(img, goodsVo.photoPath)

    local amount = GoodsUtils.GetThingNo(consume.goodsId)
    if amount >= checkInt(consume.num) then
        CfUtils.SetUISwitchText(gameObject, 1)
    else
        CfUtils.SetUISwitchText(gameObject, 3)
    end
    CfUtils.FillText(gameObject, consume.num)
end

---装备洗练
---@param consumeType integer @ConsumeType
function CardProgressionEquipmentRecastDialog:EquipmentRecast(consumeType)
    local consume = {}
    local baseConsume = nil
    if consumeType == ConsumeType.CURRENCY then
        baseConsume = self:GetCurrencyConsume()
    elseif consumeType == ConsumeType.GOODS then
        baseConsume = self:GetGoodsConsume()
    end
    --local lockPositions = ''
    table.link(consume, baseConsume)
    --if self:GetLockedAttrNum() > 0 then
    --    local lockConsume = self:GetLockConsume()
    --    table.link(consume, {lockConsume})
    --    lockPositions = self:GetLockPositions()
    --end
    
    -- 检查消耗
    for i, v in ipairs(consume) do
        if GoodsUtils.GetThingNo(checkNumber(v.goodsId)) < checkInt(v.num) then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            --local excludeIds = {
            --    { id = Constants.UITypeIds.CultivateMain},
            --    { id = Constants.UITypeIds.CultivateOverseaEquipmentClearDialog},
            --}
            --if checkNumber(v.goodsId) == Constants.Currency.FreeDiamondId then
            --    GameUtils.SecondConfirm
            --    (
            --            localize("_name_不足, 是否前往充值？", {_name_ = vo.name}),
            --            function()
            --                local OverseaStoreUtils = import('Game.OverseaStore.OverseaStoreUtils')
            --                local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
            --                OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.TopUp, excludeIds)
            --            end
            --    )
            --else
                if #checkTable(vo.jumpAway) > 0 then
                    GoodsUtils.CheckConsumeDataCondition({{goodsId = v.goodsId, num = checkInt(v.num), gainNum = checkInt(v.num) - GoodsUtils.GetThingNo(checkNumber(v.goodsId))}})
                else
                    GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
                end
                if self._autoModel then
                    self:StopAutoModel()
                end
            --end
            return
        end
    end
    
    local function request()
        local consumeData = GoodsUtils.CheckGoodConsume(consume)

        local requestData = {
            playerEquipmentId = self:GetEquipDojo().id,
            resetPosition = self._selectedAttrIdx
            --lockPositions = lockPositions,
            --consumeType = consumeType
        }
        self._isRequest = true
        CardProgressionMgr:RequestOverseaEquipmentResetAttr(requestData, consumeData, Bind(self, self.EquipmentRecastResponseHandler))
    end
    
    -- 检查品质
    local equipDojo = self:GetEquipDojo()
    local quality = equipDojo[string.format('attr%dQuality', self._selectedAttrIdx)]
    if checkInt(quality) >= 5 and not self._autoModel then
        GameUtils.SecondConfirm(localize("存在稀有词条，是否确认洗练?"), function()
            request()
        end)
        return
    end

    request()
end

