---检查是否显示二级确认框
function CardProgressionEquipmentRecastDialog:CheckShowSecondConfirm()
    local localData = CfUtils.GetLocalData("EquipmentCuringSecondConfirm", 0)
    if checkNumber(localData) == 0 then return true end

    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComp.playerDojo
    local serverTime = playerDojo:GetLoginServerTime()
    local serverTimezone = playerDojo:GetServerTimezone()
    local curDate = os.date('!*t', serverTime + serverTimezone - 3600 * 5)
    local recodeDate = os.date('!*t', localData + serverTimezone - 3600 * 5)
    if curDate.year == recodeDate.year and curDate.month == recodeDate.month and curDate.day == recodeDate.day then
        return false
    else
        return true
    end
end

