    self._autoFilter = filter
    self._autoModel = true
    self._autoTimeRecord = os.clock()
    
    self:StartAutoTimer()
    self:RefreshButton()
end

---停止自动模式
function CardProgressionEquipmentRecastDialog:StopAutoModel()
    self._autoFilter = nil
    self._autoModel = false
    self._autoTimeRecord = 0
    
    self:CloseAutoTimer()
    self:RefreshButton()
end

---开启自动模式定时器
function CardProgressionEquipmentRecastDialog:StartAutoTimer()
    self:CloseAutoTimer()
    self._autoTimeRecord = os.clock()
    CfUtils.TimerAppend(Constants.TimerName.EquipmentRecastAutoTimer, 0.1, Bind(self, self.AutoTimerUpdateHandler))
end

---关闭自动模式定时器
function CardProgressionEquipmentRecastDialog:CloseAutoTimer()
    CfUtils.TimerRemove(Constants.TimerName.EquipmentRecastAutoTimer)
end

---自动模式请求处理
function CardProgressionEquipmentRecastDialog:CheckAutoModel(playerEquipment)
    if not self._autoModel then return end

    local id = playerEquipment[string.format('attr%dId', self._selectedAttrIdx)]
    local quality = playerEquipment[string.format('attr%dQuality', self._selectedAttrIdx)]
    -- 属性是否符合
    local isAttrConform = false
    for k, v in pairs(self._autoFilter[tostring(Constants.EquipmentAutoRecastFilterType.Attribute)]) do
        if v then
            if checkInt(k) == checkInt(id) then
                isAttrConform = true
                break
            end
        end
    end
    
    -- 品质是否符合 
    local isQualityConform = false
    for k, v in pairs(self._autoFilter[tostring(Constants.EquipmentAutoRecastFilterType.Quality)]) do
        if v then
            if checkInt(quality) >= checkInt(k) then
                isQualityConform = true
            end 
            break
        end
    end
    if isAttrConform and isQualityConform then
        GameUtils.Toast(localize("洗练完成"))
        self:StopAutoModel()
    else
        self._autoTimeRecord = os.clock()
    end
end

---获取货币消耗
function CardProgressionEquipmentRecastDialog:GetCurrencyConsume()
    local equipDojo = self:GetEquipDojo()
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId) or {}
    local consume = clone(equipVo.consumeItem)
    for i, v in ipairs(consume) do
        v.num = v.goodsNum
    end
    return consume
end

---获取道具消耗
function CardProgressionEquipmentRecastDialog:GetGoodsConsume()
    local equipDojo = self:GetEquipDojo()
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId) or {}
    local consume = clone(equipVo.consume)
    for i, v in ipairs(consume) do
        v.num = v.goodsNum
    end
    return consume
end

---获取锁定消耗
function CardProgressionEquipmentRecastDialog:GetLockConsume()
    local lockConsume = {}
    local lockedNum = self:GetLockedAttrNum()
    if lockedNum > 0 then
        lockConsume.goodsId = cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentRecastLockGoodsId)
        lockConsume.consumeNum = parse_strings(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentRecastLockGoodsNums))[lockedNum]
        lockConsume.num = lockConsume.consumeNum
    end
    return lockConsume
end

---获取锁定属性数量
function CardProgressionEquipmentRecastDialog:GetLockedAttrNum()
    local equipDojo = self:GetEquipDojo()
    local lockedNum = 0
    for i = 1, checkInt(equipDojo.star) do
        if self._selectedDict[i] then
            lockedNum = lockedNum + 1
        end
    end
    return lockedNum
end

---获取锁定位置
function CardProgressionEquipmentRecastDialog:GetLockPositions()
    local tmp = {}
    for i = 1, self._subAttrMaxCount do
        if self._selectedDict[i] then
            table.insert(tmp, i)
        end
    end
    local strs = table.concat(tmp, ",")
    return strs
end

---获取EquipDojo
function CardProgressionEquipmentRecastDialog:GetEquipDojo()
    return self._equipDojo
end

---获取AttrNodeScr
---@return CardProgressionEquipmentRecastAttrNode
function CardProgressionEquipmentRecastDialog:GetAttrNodeScr(index)
    if not index then return end
    local node = self.ATKNumericalValue:Find("SubAttrNode" .. tostring(index))
    return CfUtils.GetLuaScr(node, "Game.CardProgression.Equip.CardProgressionEquipmentRecastAttrNode")
end
--endregion private

return CardProgressionEquipmentRecastDialog